from pathlib import Path
import base64,hashlib,json,zlib
ROOT=Path('portable'); APP=ROOT/'app_payload'
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def dec(s): return zlib.decompress(base64.b64decode(s))
def rr(p,start,end,new):
    b=p.read_bytes(); s=b.index(start); e=b.index(end,s); p.write_bytes(b[:s]+new+b[e:])

